def add(area,title,steps,expected,kind='Negative',priority='P0',source='',gate='Testnet release',pre=None):
    n=1+sum(c['id'].startswith('KLM-V2-'+area+'-') for c in cases)
    cases.append(dict(id=f'KLM-V2-{area}-{n:03}',phase='V2',area=area,title=title,type=kind,priority=priority,
      preconditions=pre or 'Frozen candidate; isolated migrated DB/Redis and disposable fixtures for mutations. Live browser reads may use the team Testnet host. Wallet signs remain deliberate and private.',
      steps=steps,expected=expected,evidence_required='Exact candidate, input fixture ID, expected/actual result, safe screenshot or response, and durable-state/ledger checks where relevant. No OTP, token, phrase, private CSV or full claim URL.',
      harness='Current source tests + isolated API fixture; real UI/device/ledger when named',issue='',status='Not Run',actual='',evidence='',defect='',candidate=CANDIDATE,tester='',executed_at_utc='',notes='',platforms='Desktop + Android emulator; repeat wallet handoffs on physical Android',gate=gate,source=source))

