for api in INV['apis']:
    route=api['route']; method=api['method']; public=route.startswith('/api/claims/') or route in ['/api/auth/login','/api/auth/sso/start','/api/auth/sso/callback','/api/invite/redeem','/api/stellar/network','/api/health','/api/ready','/api/status']
    credential='intended public proof/schema' if public else 'required session/key/SCIM credential and least-privileged role'
    add('API',f'{method} {route}',f'In isolated fixture server: 1. Send valid {method} with {credential}. 2. Repeat missing/expired/wrong-scope credential, foreign object ID and unknown ID. 3. For bodies test malformed JSON, extra fields, secret-shaped fixture, wrong types and schema boundaries. 4. For mutation replay identical idempotency key, changed-body key and concurrent calls; for reads test stable pagination/query bounds. 5. Compare durable state before/after every rejected request.',
      'Valid request follows its handler contract; expected4xx uses safe problem details and leaves state unchanged; no authorization/seed bypass, duplicate asset action or private data. Public routes are not incorrectly expected to require an admin session. Record exact code from applicable handler before execution.',kind='API contract / authorization / boundary',source=f"{api['source']}:{api['line']}",gate='Configured feature' if '/scim/' in route or '/sso/' in route else 'Testnet release')
