SECTIONS=[
('Purpose and build boundary',f"Comprehensive regression plan for candidate {CANDIDATE}. Kleym source is available. 24 page routes, 96 API files / 121 method handlers and the static control register are inventoried. A source declaration is not proof of a working button; conditional states and every data-bound row still require execution. No finite test plan proves all possible inputs. This plan covers observable journeys, failures, boundaries, roles and lifecycle transitions; residual risks remain explicit. Older v1 artifacts are preserved."),
('Current environments and entry gates','G0: freeze SHA/tree/lockfile and deployed web/worker/landing identities. G1: isolated populated PostgreSQL and Redis with resettable disposable users, roles, keys, provider fixtures and approved test budgets. G2: Testnet passphrase Test SDF Network ; September 2015, official USDC issuer GBBD47IF6LWK7P7MDEVSCWR7DPUWV3NY3DTQEVFL4NAT4AQH3ZLLFLA5 and fresh Horizon snapshots before every write. G3: team app https://kleym-testnet.up.railway.app and static home https://kleym-home-testnet.up.railway.app. Mainnet is disabled and has no approved separate URL. Current credentials are injected privately, never copied into the plan.'),
('Platform matrix and Android Studio','Desktop: Brave/Chrome with Freighter extension; Firefox/WebKit compatibility where supported. Android: dedicated Android Studio AVD kleym-qa-api36 using existing API36.1 Google Play x86_64 image, Pixel6 geometry1080x2400/420dpi,3GiB RAM,2cores; data on D:/Android-AVDs. Emulator is actual Android, not viewport emulation, but does not qualify OEM lifecycle, real biometrics, Play Integrity or every physical device. Physical Freighter v1.26.29 desktop/Android EMAIL success is prior evidence on merge623e2bc, not automatically a full v2 pass. Lantern is deferred until an approved curated build includes Kleym.'),
('Fixtures and exact accounting','Use two disposable organisations and OWNER/APPROVER/OPERATOR/VIEWER plus system-admin identities; never alter the real operator role/password. Test funded and literal-zero-XLM sponsored senders; recipient absent/existing-no-trustline/existing-trustline. Assets: official TestnetUSDC andXLM; custom issuer only for freeze/revoke/conversion faults. Main tutorial:3links x1USDC, desktop claim, Android claim and unused expiry reclaim. Final owner net debit2; recipients +1each; reclaim+1; exact fees and reserve deltas from Horizon. Custom prizes20,15,10,5,5=55 are fixture-only until approved balance budget exists. Pure int64 extremes never go on-chain.'),
('Execution sequence','1. Source/runtime identity, CI and security prerequisites. 2. Static homepage/login, all role-based page/control smoke on desktop and emulator. 3. Invalid input/CSV/policy matrices using isolated fixtures. 4. Real DB/Redis concurrency, crash recovery and queues. 5. Deliberate wallet Testnet creation/export/funding/claim/reclaim matrix. 6. State/compatibility/a11y/performance and cold-recipient UAT. 7. Backup/restore, monitoring and release rehearsal. Re-run affected regressions after any defect patch and freeze the new candidate; never silently combine results from different builds.'),
('Runbook: guided three-link campaign','Login on approved Testnet host. Select intended sender or manually paste its G-address for balance lookup; manual entry does not authorize signing. Create3links/1USDC, labels Desktop/Android/Unused, choose appropriate expiry and policy. Review count,total,issuer,deadline,reserves,fees. Generate keys privately, save phrase and current secrets export, approve one intended funding batch. Wait for ledger confirmation. Claim desktop link to controlled receiver, Android link in emulator/Freighter if installed and independently snapshot balances. Leave third unused; after actual expiry approve sender reclaim and reconcile. Do not share secrets/export in evidence. For EMAIL upload owned-inbox assignment before review; use new OTP only. For WALLET enforce the assigned owner. Do not reuse settled links to obtain screenshots.'),
('Evidence and status rules','Catalog rows begin Not Run; expected results are written before execution. Execution records need caseID,candidate,platform/tester/UTC,input-fixture,actual,status,evidence and defect. Statuses: Not Run,Ongoing,Passed,Failed,Blocked,For Re-test,N/A. Blocked needs a named missing prerequisite and cause class (tester, infrastructure, dependency, product). Not Run is not a failure or a pass. N/A needs explicit scope reason. CI proof qualifies only what the named scripts actually executed. Reusing same-candidate immutable CI evidence avoids unnecessary full-suite reruns; prior SHA/device proof stays separately labelled. Store safe evidence under evidences/runs/<run>/<caseID>; sanitize screenshots, HAR and logs before retention.'),
('Money, secrets and stop conditions','Stop on network/issuer/signer mismatch, unintended approval/broadcast, seed/phrase/bearer leakage, unexplained principal/reserve loss, double payout, false ledger-success state or candidate mismatch. Never persist private keys, OTP values, session/API tokens, private recipient lists, raw claim URLs or secret-bearing XDR dumps in test artifacts. The chain is authoritative. HTTP202 is not delivered mail, submitted is not funded, expired is not automatically refunded, and unchanged native balance does not by itself prove reserves released. Compare charged fees and live reserve obligations, retaining recipient permanent sponsorship separately.'),
('Release gates and current gaps','All mandatory financial/authentication/recovery cases must pass with required evidence; unresolved critical/high, mandatory Blocked or Not Run prevents full sign-off. Plan completion does not enable Mainnet. Mainnet needs separate approved HTTPS deployment/credentials/queues, sponsor/treasury and incident ownership, measured restore/rollback/alert proof, sender authentication/provider tracking confirmation and explicit real-asset pilot approval. No arbitrary global campaign-USDC cap is introduced; wallet capacity, protocol precision and sponsor admission remain. Automated treasury refill is not presumed implemented. EMAIL/CODE are application gates rather than additional on-chain signer restrictions; WALLET binds the assigned owner on-chain.'),
('Traceability and reference method','Stable original KLM-D1..D4 IDs retained; new KLM-V2 cases cover current features, each page, each API handler and every declared claim state. Controls sheet lists every static JSX declaration with source line and an explicit execution field. D1-D4 Lantern methodology is reused for independent money proof, adversarial boundaries, installed-artifact identity and cold-recipient UAT; Lantern contract addresses and its product assumptions are not copied. Automated proof, deployed smoke, physical-device proof and operational sign-off remain distinct.')]

md=['# Kleym comprehensive regression test plan v2','',f"Prepared 26 October 2026. Candidate `{CANDIDATE}`. **{len(cases)} planned cases; no blanket completion claim.**",'']
for title,body in SECTIONS: md += ['## '+title,'',body,'']
for c in cases: md += [f"### {c['id']} — {c['title']}",'',f"{c['priority']} | {c['type']} | {c['gate']} | Not Run",'', '**Preconditions:** '+c['preconditions'],'','**Steps:** '+c['steps'],'','**Expected:** '+c['expected'],'','**Evidence:** '+c['evidence_required'],'','**Source/harness:** '+c['source']+'; '+c['harness'],'']
(OUT/'TEST-PLAN-v2.md').write_text('\n'.join(md)+'\n',encoding='utf-8')

styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='BodyQA',fontName='Helvetica',fontSize=9,leading=13,spaceAfter=8)); styles.add(ParagraphStyle(name='SmallQA',fontName='Helvetica',fontSize=8,leading=11,spaceAfter=5)); styles.add(ParagraphStyle(name='BandQA',fontName='Helvetica-Bold',fontSize=20,leading=25,textColor=white)); styles['Heading2'].textColor=HexColor('#354f6e')
def p(t,style='BodyQA'): return Paragraph(escape(str(t)).replace('\n','<br/>'),styles[style])
width=A4[0]-80
band=Table([[p('KLEYM / QUALITY ASSURANCE\nComprehensive regression plan v2','BandQA')]],colWidths=[width]);band.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),HexColor('#354f6e')),('TOPPADDING',(0,0),(-1,-1),18),('BOTTOMPADDING',(0,0),(-1,-1),18)]))
flow=[band,Spacer(1,16),p('26 October 2026 | Desktop + Android | Testnet and Mainnet preparation'),p(f"{len(cases)} detailed cases | {INV['counts']['pages']} pages | {INV['counts']['apiMethods']} API methods | {INV['counts']['controlDeclarations']} static control declarations"),p('PLAN + TRACEABLE CHECKLIST. All catalog statuses start Not Run. Executed evidence is reported separately.'),p('Candidate: '+CANDIDATE,'SmallQA')]
for i,(title,body) in enumerate(SECTIONS):
    if i in [2,4,6,8]:flow.append(PageBreak())
    flow.extend([p(title,'Heading2'),p(body)])
for area in dict.fromkeys(c['area'] for c in cases):
    flow.extend([PageBreak(),p('Detailed cases / '+area,'Heading2')])
    for c in [x for x in cases if x['area']==area]:
        rows=[[p(label,'SmallQA'),p(c[key],'SmallQA')] for label,key in [('Preconditions','preconditions'),('Steps / inputs','steps'),('Expected','expected'),('Proof','evidence_required'),('Source / mode','source')]]
        table=Table(rows,colWidths=[78,width-78]);table.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('BACKGROUND',(0,0),(0,-1),HexColor('#e2f5ec')),('LINEBELOW',(0,0),(-1,-1),.3,HexColor('#d8dee9')),('LEFTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
        flow.append(KeepTogether([p(c['id']+' / '+c['title'],'Heading3'),p(c['priority']+' | '+c['type']+' | '+c['gate']+' | Not Run','SmallQA'),table,Spacer(1,10)]))
def footer(canvas,doc):
    canvas.setFont('Helvetica',8);canvas.setFillColor(HexColor('#64748b'));canvas.drawString(40,20,'Kleym QA | v2 | 26 October 2026 | Plan, not full execution certification');canvas.drawRightString(A4[0]-40,20,str(doc.page))
pdf=OUT/'kleym-comprehensive-test-plan-v2.pdf';SimpleDocTemplate(str(pdf),pagesize=A4,leftMargin=40,rightMargin=40,topMargin=36,bottomMargin=38,title='Kleym comprehensive regression plan v2',author='Kleym QA').build(flow,onFirstPage=footer,onLaterPages=footer)

wb=Workbook();ws=wb.active;ws.title='README'
for row in [['Kleym comprehensive QA v2'],['Candidate',CANDIDATE],['Plan cases',len(cases)],['Catalog statuses start Not Run; observed results belong in Execution and evidence.'],['No prior pass is copied into a different build/platform.'],['Controls are static declarations, not proof of execution or complete dynamic-state enumeration.'],['Edit Test Cases and append per-platform executions; do not overwrite history.'],['Summary formulas recalculate on open; cached values not refreshed by a spreadsheet evaluator.'],['No real passwords, seeds, phrases, OTPs, private CSVs or claim URLs in this workbook.']]:ws.append(row)
fields=['id','phase','area','title','type','priority','gate','platforms','preconditions','steps','expected','evidence_required','source','harness','status','actual','evidence','defect','candidate','tester','executed_at_utc','notes']
tc=wb.create_sheet('Test Cases');tc.append(fields)
for c in cases:tc.append([c[k] for k in fields])
tc.freeze_panes='D2';tc.auto_filter.ref=tc.dimensions
dv=DataValidation(type='list',formula1='"'+','.join(STATUSES)+'"',allow_blank=False);tc.add_data_validation(dv);dv.add(f'O2:O{len(cases)+1}')
for s,color in {'Passed':'DCFCE7','Failed':'FEE2E2','Blocked':'E2E8F0','Not Run':'FEF3C7','For Re-test':'DBEAFE'}.items():tc.conditional_formatting.add(f'O2:O{len(cases)+1}',FormulaRule(formula=[f'O2="{s}"'],fill=PatternFill('solid',fgColor=color)))
summary=wb.create_sheet('Summary');summary.append(['Status','Current catalog count','Meaning'])
for n,s in enumerate(STATUSES,2):summary.append([s,f'=COUNTIF(\'Test Cases\'!O2:O{len(cases)+1},A{n})','Catalog completion, not CI assertion count'])
summary.append(['Total',f'=SUM(B2:B{len(STATUSES)+1})',f'Expected{len(cases)}']);summary.append(['Initial factual snapshot',len(cases),'Not Run at generation'])
execution=wb.create_sheet('Execution');execution.append(['Run ID','Case ID','Candidate','Platform / browser / wallet','UTC','Tester','Fixture / input','Expected','Actual','Status','Evidence','Defect','Blocker cause'])
dv2=DataValidation(type='list',formula1='"'+','.join(STATUSES)+'"',allow_blank=False);execution.add_data_validation(dv2);dv2.add('J2:J10000')
pages=wb.create_sheet('Pages');pages.append(['Route','Source','Planned case','Observed status','Evidence'])
for page in INV['pages']:pages.append([page['route'],page['source'],next(c['id'] for c in cases if c['title']=='Page contract: '+page['route']),'Not Run',''])
api=wb.create_sheet('API Matrix');api.append(['Method','Route','Source','Line','Planned case','Auth/schema/replay/ownership execution','Evidence'])
for a in INV['apis']:api.append([a['method'],a['route'],a['source'],a['line'],next(c['id'] for c in cases if c['title']==a['method']+' '+a['route']),'Not Run',''])
ctl=wb.create_sheet('Controls');ctl.append(['Control ID','Source','Line','Tag','Static text','Attributes / dynamic label','Execution status','Linked case / state','Actual','Evidence'])
for c in INV['controls']:ctl.append([c['id'],c['source'],c['line'],c['tag'],c['text'],json.dumps(c['attributes'],ensure_ascii=False),'Not Run','Assign related PAGE/feature case; exercise conditional states','',''])
env=wb.create_sheet('Environment');env.append(['Gate','Requirement','Current qualification'])
for title,body in SECTIONS[:4]:env.append([title,body,'See current execution report; no implied pass'])
defects=wb.create_sheet('Defects');defects.append(['Defect ID','Case IDs','Title','Severity','Build / platform','Reproduction','Expected','Actual','Evidence','Cause class','State','Retest'])
proof=wb.create_sheet('Existing Proof');proof.append(['Evidence','Build','Result','Limits'])
proof.append(['evidences/develop-ci.json',CANDIDATE,'All four CI jobs succeeded','Named script/fixture proof; not physical-device or full production operational qualification'])
proof.append(['docs/reviews/2026-10-26/freighter-readiness', '623e2bc + a5a80bd follow-up','Desktop and Android EMAIL claim public ledger verified;940local tests','Device flow predates shared-IP patch; prior proof not copied as catalog status'])
proof.append(['evidences/source-inventory.json',CANDIDATE,str(INV['counts']),'Static source inventory only'])
for sh in wb:
    sh.freeze_panes=sh.freeze_panes or 'A2';sh.sheet_view.showGridLines=False
    for cell in sh[1]:cell.fill=PatternFill('solid',fgColor='354F6E');cell.font=Font(color='FFFFFF',bold=True);cell.alignment=Alignment(wrap_text=True)
    for col in sh.columns:sh.column_dimensions[col[0].column_letter].width=55 if sh.title!='Test Cases' else 44
    for row in sh.iter_rows(min_row=2):
        for cell in row:cell.alignment=Alignment(wrap_text=True,vertical='top');cell.font=Font(name='Calibri',size=11)
        sh.row_dimensions[row[0].row].height=110 if sh.title in ['Test Cases','Controls'] else 55
    sh.row_dimensions[1].height=30
tc.column_dimensions['A'].width=26;tc.column_dimensions['B'].width=10;tc.column_dimensions['C'].width=14;tc.column_dimensions['J'].width=90;tc.column_dimensions['K'].width=90
summary.column_dimensions['A'].width=25;summary.column_dimensions['B'].width=22;summary.column_dimensions['C'].width=80
ctl.column_dimensions['A'].width=18;ctl.column_dimensions['B'].width=65;ctl.column_dimensions['C'].width=9;ctl.column_dimensions['D'].width=14;ctl.column_dimensions['G'].width=18
wb.calculation=CalcProperties(calcMode='auto',fullCalcOnLoad=True)
